  2017	md_is_link_destination_A(MD_CTX* ctx, OFF beg, OFF max_end, OFF* p_end,
  2018	                         OFF* p_contents_beg, OFF* p_contents_end)
  2019	{
  2020	    OFF off = beg;
  2021	
  2022	    if(off >= max_end  ||  CH(off) != _T('<'))
  2023	        return FALSE;
  2024	    off++;
  2025	
  2026	    while(off < max_end) {
  2027	        if(CH(off) == _T('\\')  &&  off+1 < max_end  &&  ISPUNCT(off+1)) {
  2028	            off += 2;
  2029	            continue;
  2030	        }
  2031	
  2032	        if(ISNEWLINE(off)  ||  CH(off) == _T('<'))
  2033	            return FALSE;
  2034	
  2035	        if(CH(off) == _T('>')) {
  2036	            /* Success. */
  2037	            *p_contents_beg = beg+1;
  2038	            *p_contents_end = off;
  2039	            *p_end = off+1;
  2040	            return TRUE;
  2041	        }
  2042	
  2043	        off++;
  2044	    }
  2045	
  2046	    return FALSE;
  2047	}
  2048	
  2049	static int
  2050	md_is_link_destination_B(MD_CTX* ctx, OFF beg, OFF max_end, OFF* p_end,
  2051	                         OFF* p_contents_beg, OFF* p_contents_end)
  2052	{
  2053	    OFF off = beg;
  2054	    int parenthesis_level = 0;
  2055	
  2056	    while(off < max_end) {
  2057	        if(CH(off) == _T('\\')  &&  off+1 < max_end  &&  ISPUNCT(off+1)) {
  2058	            off += 2;
  2059	            continue;
  2060	        }
  2061	
  2062	        if(ISWHITESPACE(off) || ISCNTRL(off))
  2063	            break;
  2064	
  2065	        /* Link destination may include balanced pairs of unescaped '(' ')'.
  2066	         * Note we limit the maximal nesting level by 32 to protect us from
  2067	         * https://github.com/jgm/cmark/issues/214 */
  2068	        if(CH(off) == _T('(')) {
  2069	            parenthesis_level++;
  2070	            if(parenthesis_level > 32)
  2071	                return FALSE;
  2072	        } else if(CH(off) == _T(')')) {
  2073	            if(parenthesis_level == 0)
  2074	                break;
  2075	            parenthesis_level--;
  2076	        }
  2077	
  2078	        off++;
  2079	    }
  2080	
  2081	    if(parenthesis_level != 0  ||  off == beg)
  2082	        return FALSE;
  2083	
  2084	    /* Success. */
  2085	    *p_contents_beg = beg;
  2086	    *p_contents_end = off;
  2087	    *p_end = off;
  2088	    return TRUE;
  2089	}
  2090	
  2091	static inline int
  2092	md_is_link_destination(MD_CTX* ctx, OFF beg, OFF max_end, OFF* p_end,
  2093	                       OFF* p_contents_beg, OFF* p_contents_end)
  2094	{
  2095	    if(CH(beg) == _T('<'))
  2096	        return md_is_link_destination_A(ctx, beg, max_end, p_end, p_contents_beg, p_contents_end);
  2097	    else
  2098	        return md_is_link_destination_B(ctx, beg, max_end, p_end, p_contents_beg, p_contents_end);
  2099	}
